export function getCorporatorsByCity(city: string): MunicipalCorporator[] {
  const c = city.toLowerCase();
  return MAJOR_MUNICIPAL_CORPORATORS.filter(item => item.city.toLowerCase() === c || item.corporationCode.toLowerCase() === c);
}

export function getCorporatorByWard(corporationCode: string, wardNo: number): MunicipalCorporator | undefined {
  return MAJOR_MUNICIPAL_CORPORATORS.find(item => item.corporationCode.toUpperCase() === corporationCode.toUpperCase() && item.wardNo === wardNo);
}
